// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address ownerActor, uint256 fund) public {
        vm.assume(ownerActor != address(0));
        vm.assume(ownerActor != address(c));
        fund = bound(fund, 1, 1e30);

        vm.deal(ownerActor, fund);

        SimpleWallet localC;
        vm.prank(ownerActor);
        localC = new SimpleWallet();

        vm.prank(ownerActor);
        (bool sent,) = address(localC).call{value: fund}("");
        require(sent, "funding failed");

        assertTrue(address(localC).balance == fund);

        vm.prank(ownerActor);
        localC.withdrawAll();

        assertTrue(address(localC).balance == 0);
    }
}
